package dev.kpetriv.sprout.core.ai

import com.google.mlkit.genai.schema.annotations.Generable
import com.google.mlkit.genai.schema.annotations.Guide

/*
 * Structured-output shapes for Gemini Nano (ML Kit GenAI structured output; the schema is generated by KSP from these
 * annotations). Everything in them is untrusted model text: it is checked by AiOutputRules before anything is shown,
 * and toString never prints it. Kept public with every property a supported type (String, Boolean, Long, List) as the
 * schema compiler requires; R8 keeps them through the module's consumer rules.
 */

/** The answer to a kindness check. */
@Generable("Whether a child's chat message is unkind, and a kinder message they could send instead")
data class KindnessOutput(
    @Guide(description = "true if the message is unkind, rude, insulting, threatening or shouting; otherwise false")
    val unkind: Boolean,
    @Guide(description = "a short kind message with the same meaning the child could send instead; empty when kind")
    val suggestion: String,
) {
    override fun toString(): String = "KindnessOutput(unkind=$unkind, suggestion=$REDACTED)"
}

/** One suggested chore. */
@Generable("A household chore suitable for the child")
data class ChoreIdea(
    @Guide(description = "short chore title, at most 60 characters")
    val title: String,
    @Guide(description = "one short sentence saying what to do")
    val description: String,
    @Guide(description = "money reward in minor units of the currency, 0 for none", minimum = 0.0, maximum = 100000.0)
    val reward: Long,
    @Guide(description = "screen-time minutes reward, 0 for none", minimum = 0.0, maximum = 120.0)
    val minutes: Long,
    @Guide(
        description = "how often the chore is due",
        enumValues = ["ANY_TIME", "EVERY_DAY", "SCHOOL_DAYS", "WEEKENDS", "WEEKLY"],
    )
    val schedule: String,
    @Guide(
        description = "day of the week for a WEEKLY chore",
        enumValues = ["MONDAY", "TUESDAY", "WEDNESDAY", "THURSDAY", "FRIDAY", "SATURDAY", "SUNDAY"],
    )
    val day: String,
) {
    override fun toString(): String =
        "ChoreIdea(title=$REDACTED, description=$REDACTED, reward=$reward, minutes=$minutes, schedule=$schedule)"
}

/** Chore suggestions. */
@Generable("Chore suggestions for a child")
data class ChoreIdeas(
    @Guide(description = "between 3 and 5 different chores", minItems = 3, maxItems = 5)
    val chores: List<ChoreIdea>,
)

/** A weekly summary. */
@Generable("A short weekly summary for a parent")
data class SummaryOutput(
    @Guide(description = "the summary: 2 to 4 sentences")
    val text: String,
) {
    override fun toString(): String = "SummaryOutput(text=$REDACTED)"
}
